<script setup lang="ts">
import { ref,onMounted,onUnmounted,computed } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Plus, Upload, FileText, ArrowUpRight, ArrowLeft, Play, RefreshCw, CheckCheck, Layers, Paperclip, ShieldCheck, X } from 'lucide-vue-next'
import { api,post,today,statusName,materialName,dateText } from '../api'
import Modal from '../components/Modal.vue'
import EmptyState from '../components/EmptyState.vue'
import QuestionEditor from '../components/QuestionEditor.vue'
const route=useRoute(),router=useRouter(),batches=ref<any[]>([]),batch=ref<any>(null),students=ref<any[]>([]),papers=ref<any[]>([]),showUpload=ref(!!route.query.new),error=ref(''),busy=ref(false),selected=ref<string[]>([]),filter=ref('all')
const files=ref<{file:File;role:string}[]>([])
const form=ref({title:'',route:String(route.query.route||'external'),purpose:'bank',material:'blank',student:'',paper:'',test_date:today()})
let timer:ReturnType<typeof setInterval>|undefined
const filtered=computed(()=>batches.value.filter(b=>filter.value==='all'||(filter.value==='todo'?b.status!=='committed':b.status==='committed')))
const showBulk=ref(false),confirmBulk=ref(false)
const eligible=computed(()=>batch.value?.questions.filter((q:any)=>q.status==='draft'&&!q.issues.length&&q.answers.length===1)||[])
async function load(){try{if(route.params.id)batch.value=await api(`batches/${route.params.id}/`);else batches.value=await api('batches/')}catch(e:any){error.value=e.message}}
onMounted(async()=>{await load();try{[students.value,papers.value]=await Promise.all([api('students/'),api('papers/')])}catch(e:any){error.value=e.message}timer=setInterval(()=>{if(batch.value&&['queued','processing'].includes(batch.value.status))load()},4000)})
onUnmounted(()=>clearInterval(timer))
function addFiles(e:Event){const input=e.target as HTMLInputElement;for(const f of Array.from(input.files||[]))files.value.push({file:f,role:form.value.material==='answered'?'student':'paper'});input.value=''}
async function upload(){busy.value=true;error.value='';try{const data=new FormData();for(const [k,v] of Object.entries(form.value)){if(v)data.append(k,v)}for(const f of files.value){data.append('files',f.file);data.append('roles',f.role)}const result=await api('batches/upload/',{method:'POST',body:data});showUpload.value=false;await router.push('/imports/'+result.id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function action(name:string){busy.value=true;error.value='';try{await post(`batches/${batch.value.id}/${name}/`);await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function merge(){busy.value=true;try{await post('questions/merge/',{ids:selected.value});selected.value=[];await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function bulk(){busy.value=true;error.value='';try{await post('questions/bulk-approve/',{items:eligible.value.map((q:any)=>({id:q.id,answer_id:q.answers[0].id}))});showBulk.value=false;confirmBulk.value=false;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><RouterLink v-if="batch" to="/imports" class="back-link"><ArrowLeft :size="15"/>资料录入</RouterLink><p v-else class="eyebrow">IMPORT CENTER</p><h1>{{batch?batch.title:'让资料，成为教学的依据'}}<span class="heading-dot">.</span></h1><p class="subtitle">{{batch?'核对题目、参考答案与分值，确认后再归档。':'系统卷、外部卷、零散错题，都从这里进入学习闭环。'}}</p></div><button v-if="!batch" class="button primary" @click="showUpload=true"><Plus :size="18"/>新建录入批次</button><button v-else class="button secondary" @click="load"><RefreshCw :size="16"/>刷新状态</button></div><div v-if="error" class="notice danger" role="alert">{{error}}</div>
 <template v-if="!batch"><div class="tabs"><button v-for="(label,key) in {all:'全部批次',todo:'待处理',done:'已归档'}" :class="{active:filter===key}" @click="filter=String(key)">{{label}}</button></div><section class="panel"><div class="table-scroll" v-if="filtered.length"><table><thead><tr><th>资料名称</th><th>材料类型</th><th>学生 / 用途</th><th>处理状态</th><th>录入日期</th><th></th></tr></thead><tbody><tr v-for="b in filtered" :key="b.id" @click="router.push('/imports/'+b.id)"><td><div class="file-cell"><span class="file-icon"><FileText :size="20"/></span><div><strong>{{b.title}}</strong><small>{{b.files.length}} 个文件 · {{b.questions.length}} 道题目</small></div></div></td><td>{{materialName[b.material]}}</td><td>{{b.student_name||'题库资料'}}</td><td><span class="status" :class="b.status">{{statusName[b.status]}}</span></td><td>{{dateText(b.created_at)}}</td><td><ArrowUpRight :size="17"/></td></tr></tbody></table></div><EmptyState v-else title="开始整理第一份资料" text="支持 PDF、JPG、PNG，可一次上传多页。"><button class="button primary" @click="showUpload=true"><Upload :size="17"/>上传资料</button></EmptyState></section><div class="notice neutral"><ShieldCheck :size="18"/><div><strong>参考答案与学生作答，始终分开保存。</strong><p>无参考答案时可使用 AI 解题，教师审核确认后再进行正式批改。</p></div></div></template>
 <template v-else><section class="panel batch-summary"><div class="inline wrap"><span class="status" :class="batch.status">{{statusName[batch.status]}}</span><span class="tag">{{materialName[batch.material]}}</span><span>{{batch.student_name||'题库资料'}}</span><span class="muted">{{batch.test_date}}</span></div><p>{{batch.message||'原件已保存，点击开始识别进行自动切题。'}}</p><div class="progress-bar"><i :style="{width:batch.progress+'%'}"></i></div><div class="inline wrap batch-buttons"><button v-if="['uploaded','blocked','failed'].includes(batch.status)&&!batch.questions.length" class="button primary" :disabled="busy" @click="action('process')"><Play :size="16"/>{{busy?'正在处理…':'开始识别 / 重试'}}</button><button v-if="batch.questions.length&&batch.status!=='committed'" class="button primary" :disabled="busy||batch.questions.some((q:any)=>q.status!=='approved')" @click="action('commit')"><CheckCheck :size="17"/>确认归档</button><RouterLink v-if="batch.status==='committed'" :to="batch.purpose==='assessment'?'/grading':'/questions'" class="button primary">{{batch.purpose==='assessment'?'前往批改工作台':'查看题库'}}<ArrowUpRight :size="16"/></RouterLink><span class="muted small">AI 调用 {{batch.ai_calls}} 次 · {{batch.usage_tokens}} tokens</span></div><div class="file-links"><a v-for="f in batch.files" :href="f.download_url" class="file-link"><Paperclip :size="14"/>{{f.original_name}}<span class="tag">{{({paper:'题目页',answer:'答案页',student:'作答页'} as any)[f.role]}}</span></a></div></section>
 <div v-if="batch.questions.length" class="toolbar"><button v-if="eligible.length" class="button secondary small" @click="showBulk=true">批量确认答案（{{eligible.length}}）</button><span class="muted small">识别出 {{batch.questions.length}} 道题 · {{batch.questions.filter((q:any)=>q.status==='approved').length}} 道已确认</span><button class="button secondary small" :disabled="selected.length<2||busy" @click="merge"><Layers :size="15"/>合并所选题块（{{selected.length}}）</button></div><div v-for="q in batch.questions" :key="q.id+':'+q.revision" class="review-question"><label v-if="q.status==='draft'" class="check-row select-question"><input v-model="selected" type="checkbox" :value="q.id"/>选择题块</label><QuestionEditor :question="q" @changed="load"/></div><EmptyState v-if="!batch.questions.length" :title="['processing','queued'].includes(batch.status)?'正在处理资料':'原件已就绪'" :text="['processing','queued'].includes(batch.status)?'任务在后台运行，可稍后回来查看。':'启动识别后，这里将展示自动切分的题目与待审核内容。'"/></template>
 <Modal v-if="showBulk" title="批量确认参考答案" wide @close="showBulk=false"><p class="helper">仅包含无待处理问题、且只有一个参考答案版本的题目。冲突与缺失题目仍需逐题审核。</p><div v-for="q in eligible" :key="q.id" class="bulk-answer"><strong>第 {{q.number}} 题 · {{q.suggested_max_score}} 分</strong><p>{{q.stem}}</p><p>参考答案：{{q.answers[0].answer}}</p></div><label class="check-row"><input v-model="confirmBulk" type="checkbox"/>我已逐题核对以上题干、参考答案及分值</label><button class="button primary full" :disabled="busy||!confirmBulk" @click="bulk">确认 {{eligible.length}} 道题入库</button><div v-if="error" class="notice danger">{{error}}</div></Modal><Modal v-if="showUpload" title="录入教学资料" wide @close="showUpload=false"><form @submit.prevent="upload"><div v-if="error" class="notice danger">{{error}}</div><div class="form-grid"><label>批次名称<input v-model="form.title" required placeholder="如：初三数学 · 学校周测" maxlength="200"/></label><label>录入路径<select v-model="form.route" @change="form.route==='card'&&(form.purpose='assessment',form.material='answered')"><option value="external">外部完整试卷</option><option value="card">系统规范答题卡</option><option value="fragment">作业与零散错题</option></select></label><label>用途<select v-model="form.purpose" :disabled="form.route==='card'"><option value="bank">收集题库资料</option><option value="assessment">学生作业 / 测试</option></select></label><label>材料类型<select v-model="form.material"><option value="blank">空白试卷（AI补全答案）</option><option value="with_answers">附参考答案（识别已有答案）</option><option value="answered">学生已作答（区分题干与作答）</option></select></label><label v-if="form.purpose==='assessment'">关联学生<select v-model="form.student" required><option value="" disabled>请选择学生</option><option v-for="s in students" :value="s.id">{{s.name}} · {{s.grade}}</option></select></label><label>测试 / 收集日期<input v-model="form.test_date" type="date" required/></label><label class="span-2">关联已有试卷{{form.route==='card'?'（必选）':'（可选：同一套卷复用于其他学生）'}}<select v-model="form.paper" :required="form.route==='card'"><option value="">不关联，识别后建立外部试卷</option><option v-for="p in papers.filter(p=>p.status==='published')" :value="p.id">{{p.title}}</option></select></label></div><label class="upload-drop"><Upload :size="29"/><strong>选择 PDF、试卷扫描件或手机照片</strong><span>支持多文件 · 单批最多 30 个文件 / 50MB</span><input type="file" accept="application/pdf,image/jpeg,image/png" multiple @change="addFiles"/></label><div v-for="(f,index) in files" :key="index" class="upload-file"><FileText :size="17"/><span>{{f.file.name}}<small>{{(f.file.size/1024).toFixed(0)}} KB</small></span><select v-model="f.role" aria-label="文件内容角色"><option value="paper">题目页</option><option value="answer">参考答案页</option><option value="student">学生作答页</option></select><button type="button" class="icon-button" aria-label="移除文件" @click="files.splice(index,1)"><X :size="16"/></button></div><p class="helper">同一批次用于一位学生；不同学生的资料请分批上传。学生手写作答不会作为标准答案。</p><button class="button primary full" :disabled="busy||!files.length"><Upload :size="17"/>{{busy?'正在上传…':'保存原件并建立批次'}}</button></form></Modal>
</template>
